import re, pathlib
root = pathlib.Path("crates/optical/src")
pats = ["rect_filled","rect_stroke","line_segment","circle_filled","circle_stroke","text","galley","image"]
counts = {p: 0 for p in pats}
shapes = {s: 0 for s in ["convex_polygon","line","closed_line","mesh"]}
for f in root.rglob("*.rs"):
    t = f.read_text(errors="ignore")
    for p in pats:
        counts[p] += len(re.findall(r"\." + p + r"\(", t))
    for s in shapes:
        shapes[s] += len(re.findall(r"Shape::" + s, t))
print("painter:", counts)
print("shapes :", shapes)
PY
